-- Haven v1 · D1 migration 0003 · initial schema (runs after 0002 removed the MVP tables)
-- Matches PRD › Technical spec (Data model, Admin site, Feedback, Region defaults).
-- Conventions:
--   ids are text (UUIDv7 or nanoid generated by the Worker)
--   timestamps are integers, milliseconds since epoch (UTC)
--   household-local dates are text 'YYYY-MM-DD'
--   household tables carry household_id, version (household change counter at last write)
--   and deleted (0/1 tombstone, purged after 30 days)

PRAGMA foreign_keys = ON;

-- ───────────── Console ─────────────

CREATE TABLE users (
  id                TEXT PRIMARY KEY,
  google_sub        TEXT NOT NULL UNIQUE,
  email             TEXT NOT NULL,
  name              TEXT NOT NULL,
  photo_url         TEXT,
  household_id      TEXT,
  theme             TEXT NOT NULL DEFAULT 'market' CHECK (theme IN ('market','tomato','night')),
  mode              TEXT NOT NULL DEFAULT 'system' CHECK (mode IN ('system','light','dark')),
  suspended_at      INTEGER,
  suspended_reason  TEXT,
  removed_notice    TEXT,                      -- JSON {household, at, by} shown once after being removed
  created_at        INTEGER NOT NULL
);
CREATE INDEX users_email ON users (email);
CREATE INDEX users_household ON users (household_id);

CREATE TABLE sessions (
  token_hash    TEXT PRIMARY KEY,           -- SHA-256 of the cookie token
  user_id       TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at    INTEGER NOT NULL,
  last_seen_at  INTEGER NOT NULL,
  expires_at    INTEGER NOT NULL,
  device        TEXT
);
CREATE INDEX sessions_user ON sessions (user_id);
CREATE INDEX sessions_expiry ON sessions (expires_at);

CREATE TABLE households (
  id                 TEXT PRIMARY KEY,
  name               TEXT NOT NULL,
  owner_id           TEXT NOT NULL REFERENCES users (id),
  timezone           TEXT NOT NULL,                       -- IANA, e.g. Europe/London
  default_servings   INTEGER CHECK (default_servings BETWEEN 1 AND 20),
  week_start         TEXT NOT NULL DEFAULT 'mon' CHECK (week_start IN ('mon','sun','sat')),
  measurement        TEXT NOT NULL DEFAULT 'metric' CHECK (measurement IN ('metric','us')),
  enabled_modules    TEXT NOT NULL DEFAULT '["meals"]',   -- JSON array
  invite_code        TEXT UNIQUE,                         -- 128-bit random code, readable by members (decision: Nov 2026)
  invite_expires_at  INTEGER,
  deleted_at         INTEGER,
  version            INTEGER NOT NULL DEFAULT 0,
  created_at         INTEGER NOT NULL
);

CREATE TABLE members (
  household_id  TEXT NOT NULL REFERENCES households (id) ON DELETE CASCADE,
  user_id       TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  role          TEXT NOT NULL CHECK (role IN ('owner','member')),
  joined_at     INTEGER NOT NULL,
  PRIMARY KEY (household_id, user_id)
);
CREATE UNIQUE INDEX members_one_household ON members (user_id);
CREATE UNIQUE INDEX members_one_owner ON members (household_id) WHERE role = 'owner';

CREATE TABLE activity (
  id            TEXT PRIMARY KEY,
  household_id  TEXT NOT NULL REFERENCES households (id) ON DELETE CASCADE,
  module_id     TEXT NOT NULL,
  member_id     TEXT,
  text          TEXT NOT NULL,
  at            INTEGER NOT NULL,
  version       INTEGER NOT NULL,
  deleted       INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX activity_sync ON activity (household_id, version);
CREATE INDEX activity_age ON activity (at);

-- ───────────── Meals & Groceries ─────────────

CREATE TABLE meals_ingredients (
  id            TEXT PRIMARY KEY,
  household_id  TEXT NOT NULL REFERENCES households (id) ON DELETE CASCADE,
  name          TEXT NOT NULL,
  default_unit  TEXT,
  section       TEXT NOT NULL CHECK (section IN ('produce','meat_fish','dairy','bakery','pantry','frozen','other')),
  merged_into   TEXT REFERENCES meals_ingredients (id),
  version       INTEGER NOT NULL,
  deleted       INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX meals_ingredients_sync ON meals_ingredients (household_id, version);
CREATE UNIQUE INDEX meals_ingredients_name ON meals_ingredients (household_id, name COLLATE NOCASE) WHERE deleted = 0 AND merged_into IS NULL;

CREATE TABLE meals_recipes (
  id             TEXT PRIMARY KEY,
  household_id   TEXT NOT NULL REFERENCES households (id) ON DELETE CASCADE,
  title          TEXT NOT NULL,
  base_servings  INTEGER NOT NULL CHECK (base_servings BETWEEN 1 AND 50),
  ingredients    TEXT NOT NULL DEFAULT '[]',  -- JSON: [{ingredient_id, qty, unit, note, group, optional, to_taste}]
  steps          TEXT NOT NULL DEFAULT '[]',  -- JSON: [string]
  tags           TEXT NOT NULL DEFAULT '[]',  -- JSON: [string]
  source         TEXT,
  photo_key      TEXT,                        -- R2 key
  archived_at    INTEGER,
  deleted_at     INTEGER,
  updated_by     TEXT,
  version        INTEGER NOT NULL,
  deleted        INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX meals_recipes_sync ON meals_recipes (household_id, version);

CREATE TABLE meals_planned (
  id                 TEXT PRIMARY KEY,
  household_id       TEXT NOT NULL REFERENCES households (id) ON DELETE CASCADE,
  date               TEXT NOT NULL,           -- YYYY-MM-DD, household time zone
  slot               TEXT NOT NULL CHECK (slot IN ('breakfast','lunch','dinner','snack')),
  recipe_id          TEXT NOT NULL,
  servings           INTEGER NOT NULL CHECK (servings BETWEEN 1 AND 50),
  status             TEXT NOT NULL DEFAULT 'planned' CHECK (status IN ('planned','skipped')),
  bought_on_trip_id  TEXT,
  recipe_snapshot    TEXT,                    -- JSON, only when the recipe was deleted
  version            INTEGER NOT NULL,
  deleted            INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX meals_planned_sync ON meals_planned (household_id, version);
CREATE INDEX meals_planned_date ON meals_planned (household_id, date);

CREATE TABLE meals_trips (
  id            TEXT PRIMARY KEY,
  household_id  TEXT NOT NULL REFERENCES households (id) ON DELETE CASCADE,
  date          TEXT NOT NULL,
  kind          TEXT NOT NULL DEFAULT 'regular' CHECK (kind IN ('regular','topup')),
  status        TEXT NOT NULL DEFAULT 'upcoming' CHECK (status IN ('upcoming','in_progress','overdue','finished')),
  finished_at   INTEGER,
  reopen_until  INTEGER,
  final_lines   TEXT,                         -- JSON, written when the trip is finished
  version       INTEGER NOT NULL,
  deleted       INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX meals_trips_sync ON meals_trips (household_id, version);
CREATE UNIQUE INDEX meals_trips_one_regular_per_day ON meals_trips (household_id, date) WHERE kind = 'regular' AND deleted = 0;

CREATE TABLE meals_items (
  household_id  TEXT NOT NULL REFERENCES households (id) ON DELETE CASCADE,
  trip_id       TEXT NOT NULL,
  key           TEXT NOT NULL,                -- ingredientId_family (e.g. abc_mass) or extra_<id>
  checked       INTEGER NOT NULL DEFAULT 0,
  checked_by    TEXT,
  checked_at    INTEGER,
  bought_qty    REAL,
  bought_unit   TEXT,
  unavailable   INTEGER NOT NULL DEFAULT 0,
  have_it       INTEGER NOT NULL DEFAULT 0,
  carried_from  TEXT,
  label         TEXT,                         -- extras only
  qty           REAL,                         -- extras only
  unit          TEXT,                         -- extras only
  section       TEXT,                         -- extras only
  version       INTEGER NOT NULL,
  deleted       INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (trip_id, key)
);
CREATE INDEX meals_items_sync ON meals_items (household_id, version);

-- ───────────── Feedback and admin ─────────────

CREATE TABLE feedback (
  id            TEXT PRIMARY KEY,
  user_id       TEXT REFERENCES users (id) ON DELETE SET NULL,
  household_id  TEXT,
  kind          TEXT NOT NULL CHECK (kind IN ('broken','idea','question')),
  status        TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','in_progress','replied','done')),
  device        TEXT,                         -- JSON, only if the user left device details on
  admin_note    TEXT,
  user_unread   INTEGER NOT NULL DEFAULT 0,
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL
);
CREATE INDEX feedback_status ON feedback (status, updated_at);
CREATE INDEX feedback_user ON feedback (user_id, updated_at);

CREATE TABLE feedback_messages (
  id           TEXT PRIMARY KEY,
  feedback_id  TEXT NOT NULL REFERENCES feedback (id) ON DELETE CASCADE,
  author       TEXT NOT NULL CHECK (author IN ('user','admin')),
  text         TEXT NOT NULL,
  created_at   INTEGER NOT NULL
);
CREATE INDEX feedback_messages_thread ON feedback_messages (feedback_id, created_at);

CREATE TABLE flags (
  key         TEXT PRIMARY KEY,
  value       TEXT NOT NULL,                  -- JSON
  updated_at  INTEGER NOT NULL
);
INSERT INTO flags (key, value, updated_at) VALUES
  ('show_planned_modules', 'false', 0),
  ('module_meals_enabled', 'true', 0),
  ('offer_install', 'true', 0);

CREATE TABLE announcements (
  id         TEXT PRIMARY KEY,
  text       TEXT NOT NULL,
  starts_at  INTEGER NOT NULL,
  ends_at    INTEGER NOT NULL,
  CHECK (ends_at > starts_at)
);

CREATE TABLE audit_log (
  id           TEXT PRIMARY KEY,
  at           INTEGER NOT NULL,
  action       TEXT NOT NULL,
  target_type  TEXT NOT NULL,
  target_id    TEXT,
  detail       TEXT                           -- JSON
);
CREATE INDEX audit_log_at ON audit_log (at);

-- Insert-only: block edits to the audit log (deletes are allowed only for the 12-month purge).
CREATE TRIGGER audit_log_no_update BEFORE UPDATE ON audit_log
BEGIN
  SELECT RAISE(ABORT, 'audit_log is insert-only');
END;

-- ───────────── Admin sign-in (Google + passkey, no Zero Trust) ─────────────

CREATE TABLE admin_passkeys (
  credential_id  TEXT PRIMARY KEY,            -- base64url WebAuthn credential id
  public_key     TEXT NOT NULL,               -- base64url COSE public key
  counter        INTEGER NOT NULL DEFAULT 0,
  name           TEXT NOT NULL,               -- e.g. "MacBook", "iPhone"
  created_at     INTEGER NOT NULL,
  last_used_at   INTEGER
);

CREATE TABLE admin_sessions (
  token_hash  TEXT PRIMARY KEY,               -- SHA-256 of the __Host-haven_admin cookie token
  created_at  INTEGER NOT NULL,
  expires_at  INTEGER NOT NULL,               -- created_at + 12 h, never extended
  passkey_at  INTEGER NOT NULL DEFAULT 0,     -- last passkey use (0 = Google only so far); destructive actions need < 15 min
  challenge   TEXT                            -- pending WebAuthn challenge
);
CREATE INDEX admin_sessions_expiry ON admin_sessions (expires_at);

CREATE TABLE admin_setup (
  code_hash  TEXT PRIMARY KEY,                -- SHA-256 of a spent ADMIN_SETUP_CODE
  used_at    INTEGER NOT NULL
);

-- ───────────── Usage snapshots (admin Health; written by the admin Worker's cron) ─────────────

CREATE TABLE usage_snapshots (
  day     TEXT NOT NULL,                      -- YYYY-MM-DD (UTC, matches Cloudflare's daily reset)
  metric  TEXT NOT NULL,                      -- worker_requests, do_requests, d1_rows_read, d1_rows_written
  value   INTEGER NOT NULL,
  at      INTEGER NOT NULL,
  PRIMARY KEY (day, metric)
);
